//! The ACES 2.0 port against OpenColorIO 2.5.2.
//!
//! `tests/data/aces2-reference.tsv` is generated by `generate_aces2.py` from
//! every ACES 2.0 output transform OpenColorIO registers, forward (ACES2065-1
//! to display XYZ) and inverse (that XYZ back). OpenColorIO computes in 32-bit
//! floats and the port in 64-bit, so agreement is to a tolerance, measured and
//! printed here, not to the bit.

use cine_color::aces2::{DisplayTransform, DISPLAYS};
use std::collections::BTreeMap;
use std::time::Instant;

/// Relative above 1e-3, absolute below.
fn error(got: [f64; 3], want: [f64; 3]) -> f64 {
    (0..3)
        .map(|c| (got[c] - want[c]).abs() / want[c].abs().max(1e-3))
        .fold(0.0, f64::max)
}

#[test]
fn the_port_matches_opencolorio_on_every_display_in_both_directions() {
    let text = include_str!("data/aces2-reference.tsv");
    let mut transforms: BTreeMap<String, DisplayTransform> = BTreeMap::new();
    let mut worst: BTreeMap<(String, String), f64> = BTreeMap::new();
    let mut failures = Vec::new();
    let mut build = std::time::Duration::ZERO;
    let mut samples = 0;
    for line in text.lines().filter(|l| !l.starts_with('#')).skip(1) {
        let f: Vec<&str> = line.split('\t').collect();
        let (name, direction) = (f[0].to_string(), f[1].to_string());
        let v: Vec<f64> = f[2..].iter().map(|s| s.parse().unwrap()).collect();
        let t = transforms.entry(name.clone()).or_insert_with(|| {
            let at = Instant::now();
            let t =
                DisplayTransform::new(&name).unwrap_or_else(|| panic!("{name} is not answered"));
            build += at.elapsed();
            t
        });
        let input = [v[0], v[1], v[2]];
        let want = [v[3], v[4], v[5]];
        let got = if direction == "forward" {
            t.to_xyz(input)
        } else {
            t.from_xyz(input)
        };
        // The inverse amplifies float32 error where the tonescale is flat
        // (near peak), so it is held to a looser bound.
        let bound = if direction == "forward" { 2e-5 } else { 2e-3 };
        let err = error(got, want);
        let w = worst
            .entry((name.clone(), direction.clone()))
            .or_insert(0.0);
        *w = w.max(err);
        if err > bound {
            failures.push(format!(
                "{name} {direction} {input:?}: {got:?} vs {want:?} ({err:.2e})"
            ));
        }
        samples += 1;
    }
    assert_eq!(
        transforms.len(),
        DISPLAYS.len(),
        "every display has references"
    );
    let fwd = worst
        .iter()
        .filter(|((_, d), _)| d == "forward")
        .map(|(_, e)| *e)
        .fold(0.0, f64::max);
    let inv = worst
        .iter()
        .filter(|((_, d), _)| d == "inverse")
        .map(|(_, e)| *e)
        .fold(0.0, f64::max);
    println!(
        "MEASURED {samples} samples over {} displays: worst forward {fwd:.2e}, worst inverse {inv:.2e}; \
         table build {:.1} ms per display",
        transforms.len(),
        build.as_secs_f64() * 1000.0 / transforms.len() as f64
    );
    assert!(
        failures.is_empty(),
        "{} samples disagree:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
